  p=[self.red((h+x)**(j-2*b)*(h*x)**b) for b in range(j//2+1)]
  M=S.Matrix([[S.Poly(f,h,x).coeff_monomial(h**(j-b)*x**b) for f in p] for b in range(j+1)])
  return [p[k] for k in M.rref()[1]]
 def total(self,parts):
